import * as fs from "fs";
import * as path from "path";
import { fileURLToPath } from "node:url";
import fetchConfigById from "./utils/fetchConfigById";
import { Tokenizer } from "../src";
import type { TruncationStrategy } from "../src";

const __dirname = path.dirname(fileURLToPath(import.meta.url));

// Generated by tests/py/generate_truncation_oracle.py from the Python `tokenizers` library.
const ORACLE: {
  tokenizers_version: string;
  models: Record<
    string,
    Record<
      string,
      {
        text: string;
        text_pair: string | null;
        max_length: number;
        truncation: TruncationStrategy;
        add_special_tokens: boolean;
        ids: number[];
      }
    >
  >;
} = JSON.parse(fs.readFileSync(path.join(__dirname, "fixtures", "truncationOracle.json"), "utf-8"));

const LONG = "The quick brown fox jumps over the lazy dog while the cat watches from the old wooden fence.";

describe(`Truncation matches Python tokenizers ${ORACLE.tokenizers_version}`, () => {
  for (const [modelId, cases] of Object.entries(ORACLE.models)) {
    describe(modelId, () => {
      let tokenizer: Tokenizer;

      beforeAll(async () => {
        const { tokenizerJson, tokenizerConfig } = await fetchConfigById(modelId);
        tokenizer = new Tokenizer(tokenizerJson, tokenizerConfig);
      });

      for (const [name, c] of Object.entries(cases)) {
        test(name, () => {
          const encoded = tokenizer.encode(c.text, {
            text_pair: c.text_pair,
            add_special_tokens: c.add_special_tokens,
            truncation: c.truncation,
            max_length: c.max_length,
          });
          expect(encoded.ids).toEqual(c.ids);
          expect(encoded.ids.length).toBeLessThanOrEqual(c.max_length);
        });
      }
    });
  }
});

describe("Truncation edge cases", () => {
  let tokenizer: Tokenizer;

  beforeAll(async () => {
    const { tokenizerJson, tokenizerConfig } = await fetchConfigById("Xenova/bert-base-uncased");
    tokenizer = new Tokenizer(tokenizerJson, tokenizerConfig);
  });

  test("truncation: true means longest_first", () => {
    const a = tokenizer.encode(LONG, { truncation: true, max_length: 8 });
    const b = tokenizer.encode(LONG, { truncation: "longest_first", max_length: 8 });
    expect(a.ids).toEqual(b.ids);
    expect(a.ids.at(-1)).toBe(102); // [SEP] kept
  });

  test("no truncation by default", () => {
    const full = tokenizer.encode(LONG);
    expect(tokenizer.encode(LONG, { max_length: 8 }).ids).toEqual(full.ids);
  });

  test("attention_mask and token_type_ids follow the truncated ids", () => {
    const encoded = tokenizer.encode(LONG, {
      text_pair: LONG,
      truncation: true,
      max_length: 11,
      return_token_type_ids: true,
    });
    expect(encoded.ids).toHaveLength(11);
    expect(encoded.attention_mask).toHaveLength(11);
    expect(encoded.token_type_ids).toHaveLength(11);
  });

  // Rust tokenizers >= 1.0 (truncate_pair): a max_length that leaves no room
  // after the special tokens yields only the special tokens.
  test("max_length smaller than the special tokens keeps only them", () => {
    expect(tokenizer.encode(LONG, { truncation: true, max_length: 1 }).ids).toEqual([101, 102]);
  });

  test("only_second without a pair throws", () => {
    expect(() => tokenizer.encode(LONG, { truncation: "only_second", max_length: 8 })).toThrow("second sequence not provided");
  });

  test("a sequence too short to absorb the cut throws", () => {
    expect(() => tokenizer.encode("Hi.", { text_pair: LONG, truncation: "only_first", max_length: 8 })).toThrow("too short");
  });

  test("truncation without max_length throws", () => {
    expect(() => tokenizer.encode(LONG, { truncation: true })).toThrow("max_length");
  });
});
